<?php
declare(strict_types=1);
require_once __DIR__.'/bootstrap/app.php';
$user=pf_require_login($pdo);
$q=$pdo->prepare("SELECT c.id,c.title,c.status,c.currency,s.placement_key,s.requested_budget,s.starts_at,s.ends_at,(SELECT COUNT(*) FROM pf_site_ad_events e WHERE e.campaign_id=c.id AND e.event_type='IMPRESSION') impressions,(SELECT COUNT(*) FROM pf_site_ad_events e WHERE e.campaign_id=c.id AND e.event_type='CLICK') clicks FROM pf_campaigns c JOIN pf_site_campaigns s ON s.campaign_id=c.id WHERE c.advertiser_id=? AND c.campaign_type='SITE_DISPLAY' ORDER BY c.created_at DESC");
$q->execute([(int)$user['id']]);$campaigns=$q->fetchAll();
?>
