<main class="container"><section class="welcome"><p class="eyebrow">ADVERTISING CAMPAIGNS</p><h1>Your main-site campaigns</h1><p class="muted">Review schedules, moderation status and delivery metrics. Impressions and clicks are reporting metrics, not guaranteed volumes.</p><p><a class="button primary" href="create-campaign.php">Create a campaign</a></p></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Campaign</th><th>Placement</th><th>Dates</th><th>Budget</th><th>Impressions</th><th>Clicks</th><th>Status</th><th>Action</th></tr></thead><tbody>
<?php foreach($campaigns as $c):?><tr><td><?=pf_e($c['title'])?></td><td><?=pf_e($c['placement_key'])?></td><td><?=pf_e(substr((string)$c['starts_at'],0,10))?> – <?=pf_e(substr((string)$c['ends_at'],0,10))?></td><td><?=pf_e($c['currency'])?> <?=number_format((float)$c['requested_budget'],2)?></td><td><?=number_format((int)$c['impressions'])?></td><td><?=number_format((int)$c['clicks'])?></td><td><?=pf_e($c['status'])?></td><td><?php if($c['status']==='DRAFT'):?><a href="fund-site-campaign.php?id=<?=(int)$c['id']?>">Review & reserve</a><?php else:?>—<?php endif;?></td></tr><?php endforeach;?><?php if(!$campaigns):?><tr><td colspan="8">You have not created a main-site campaign yet.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
